import type { Transform } from './types.js'

export type TransformRunResult = {
  error?: Error
  filesChanged: string[]
  name: string
  notes?: string[]
}

export type RunTransformsResult = {
  failed: boolean
  results: TransformRunResult[]
}

/**
 * Runs all supplied transforms in order against a ts-morph `Project`.
 *
 * Continues past any transform that throws, collecting results from every
 * transform. Returns `failed: true` if any transform threw an error.
 */
export async function runTransforms({
  project,
  transforms,
}: {
  project: Project
  transforms: Transform[]
}): Promise<RunTransformsResult> {
  const results: TransformRunResult[] = []
  let failed = false

  for (const transform of transforms) {
    try {
      const result = await transform.apply({ project })
      results.push({
        name: transform.name,
        filesChanged: result.filesChanged,
        notes: result.notes,
      })
    } catch (err) {
      failed = true
      results.push({
        name: transform.name,
        error: err instanceof Error ? err : new Error(String(err)),
        filesChanged: [],
      })
    }
  }

  return { failed, results }
}
